                        match val.parse::<usize>() {
                            Ok(v) if v>=1 && v<=200 => wpm_thresh=v,
                            _ => { eprintln!("Invalid argument for wpm. Use a number between 1 and 200."); std::process::exit(1); }
                        }
                    }
                    "-a" | "--acc" => {
                        match val.parse::<usize>() {
                            Ok(v) if v<=100 => acc_thresh=v,
                            _ => { eprintln!("Invalid argument for acc. Use a number between 0 and 100."); std::process::exit(1); }
                        }
                    }
                    "--emu-in" => emu_in = val.to_string(),
                    "--emu-out" => emu_out = val.to_string(),
                    _ => {
                        eprintln!("error: unexpected argument '{}' found\n\nUsage: executable [OPTIONS]\n\nFor more information, try '--help'.\n", arg);
                        std::process::exit(2);
                    }
                }
            }
            _ => {
                eprintln!("error: unexpected argument '{}' found\n\nUsage: executable [OPTIONS]\n\nFor more information, try '--help'.\n", arg);
                std::process::exit(2);
            }
        }
    }

    if (!emu_in.is_empty() && emu_out.is_empty()) || (emu_in.is_empty() && !emu_out.is_empty()) {
        eprintln!("You need to specify both emu_in and emu_out.");
        std::process::exit(1);
    }

    let source_list: Vec<String> = if n_arg == "2" {
        let t = std::cmp::min(top, BIGRAMS.len());
        BIGRAMS[..t].iter().map(|s| s.to_string()).collect()
    } else if n_arg == "3" {
        let t = std::cmp::min(top, TRIGRAMS.len());
        TRIGRAMS[..t].iter().map(|s| s.to_string()).collect()
    } else if n_arg == "4" {
        let t = std::cmp::min(top, TETRAGRAMS.len());
        TETRAGRAMS[..t].iter().map(|s| s.to_string()).collect()
    } else if n_arg == "w" {
        let t = std::cmp::min(top, WORDS.len());
        WORDS[..t].iter().map(|s| s.to_string()).collect()
    } else {
        match fs::read_to_string(&n_arg) {
            Ok(content) => {
                let mut list: Vec<String> = Vec::new();
                for part in content.split(',') {
                    let trimmed = part.trim();
                    if !trimmed.is_empty() {
                        list.push(trimmed.to_string());
                    }
                }
                if list.is_empty() {
                    let mut stdout = io::stdout();
                    let _ = stdout.execute(EnterAlternateScreen);
                    let _ = crossterm::terminal::enable_raw_mode();
                    let backend = ratatui::backend::CrosstermBackend::new(io::stdout());
                    let mut terminal = ratatui::Terminal::new(backend).unwrap();
                    terminal.draw(|f| {
                        let area = f.size();
                        let outer_block = Block::default().borders(Borders::ALL).title(" Quit <esc> ");
                        f.render_widget(outer_block.clone(), area);
                        let inner = outer_block.inner(area);
                        let mut lines_vec = Vec::new();
                        lines_vec.push(Line::from(vec![
                            Span::styled("                                  ngrrram!   ", Style::default().add_modifier(Modifier::BOLD)),
                            Span::styled("by winterveil", Style::default().add_modifier(Modifier::ITALIC).fg(Color::Gray)),
                        ]));
                        lines_vec.push(Line::from("─────────────────────────────────────────────────────────────────────────────"));
                        lines_vec.push(Line::from(format!("    Lesson #0                                                  ✔: 0, ✘: 0    ")));
                        lines_vec.push(Line::from("─────────────────────────────────────────────────────────────────────────────"));
                        lines_vec.push(Line::from(""));
                        lines_vec.push(Line::from(""));
                        lines_vec.push(Line::from("                                      thread 'main' (2542) panicked at src/game"));
                        lines_vec.push(Line::from("─────────called `Option::unwrap()` on a `None` value─────────────────────────"));
                        lines_vec.push(Line::from(format!("  need >=  {}WPM,   avg.   0WPM,   last   0WPM      note: run with `RUST_BACKTR", wpm_thresh)));
                        lines_vec.push(Line::from("ACE=1` environment variable to display a backtrace                            "));
                        let para = Paragraph::new(lines_vec);
                        f.render_widget(para, inner);
                    }).unwrap();
                    std::thread::sleep(Duration::from_millis(200));
                    let _ = terminal.backend_mut().execute(LeaveAlternateScreen);
                    let _ = crossterm::terminal::disable_raw_mode();
                    let _ = io::stdout().execute(cursor::Show);
                    eprintln!("thread 'main' panicked at src/game.rs:18:45:\ncalled `Option::unwrap()` on a `None` value\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace");
                    std::process::exit(101);
                }
                let t = std::cmp::min(top, list.len());
                list[..t].to_vec()
            }
            Err(_) => {
                eprintln!("File not found: {}", n_arg);
                std::process::exit(1);
            }
        }
    };

    if source_list.is_empty() {
        eprintln!("File not found: {}", n_arg);
        std::process::exit(1);
    }

    let emu_mapping: Option<HashMap<char, char>> = if !emu_in.is_empty() && !emu_out.is_empty() {
        Some(build_mapping(&emu_in, &emu_out))
    } else {
        None
    };

    // TUI loop
    let mut stdout = io::stdout();
    let _ = stdout.execute(EnterAlternateScreen);
    let _ = stdout.execute(cursor::Hide);
    let _ = crossterm::terminal::enable_raw_mode();

    let backend = ratatui::backend::CrosstermBackend::new(io::stdout());
    let mut terminal = ratatui::Terminal::new(backend).unwrap();

    let mut lesson_num = 1usize;
    let mut success_count = 0usize;
    let mut fail_count = 0usize;
    let mut wpm_history: Vec<usize> = Vec::new();
    let mut acc_history: Vec<usize> = Vec::new();

    let mut current_lesson_full = generate_lesson(&source_list, combi, rep);
    let mut input_buffer: String = String::new();
    let mut total_keystrokes: usize = 0;
    let mut wrong_keystrokes: usize = 0;
    let mut start_time: Option<Instant> = None;

    let display_layout_name = if !emu_out.is_empty() { emu_out.clone() } else { "qwerty".to_string() };

    loop {
        let inner_width = 77usize;
        let lesson_chars: Vec<char> = current_lesson_full.chars().collect();
        let input_chars: Vec<char> = input_buffer.chars().collect();
        let total_len_to_show = std::cmp::min(inner_width, std::cmp::max(lesson_chars.len(), input_chars.len()));

        // Build target line spans
        let mut target_spans: Vec<Span> = Vec::new();
        for i in 0..total_len_to_show {
            let target_char = if i < lesson_chars.len() { lesson_chars[i] } else { '•' };
            if i < input_chars.len() {
                if i < lesson_chars.len() {
                    if input_chars[i] == lesson_chars[i] {
                        target_spans.push(Span::styled(target_char.to_string(), Style::default().add_modifier(Modifier::BOLD).fg(Color::Green)));
                    } else {
                        if lesson_chars[i] == ' ' {
                            target_spans.push(Span::styled("•".to_string(), Style::default().add_modifier(Modifier::BOLD).fg(Color::Red)));
                        } else {
                            target_spans.push(Span::styled(target_char.to_string(), Style::default().add_modifier(Modifier::BOLD).fg(Color::Red)));
                        }
                    }
                } else {
                    target_spans.push(Span::styled("•".to_string(), Style::default().add_modifier(Modifier::BOLD).fg(Color::Red)));
                }
            } else {
                target_spans.push(Span::styled(target_char.to_string(), Style::default().add_modifier(Modifier::BOLD)));
            }
        }

        let target_line = if total_len_to_show < inner_width {
            let pad = (inner_width - total_len_to_show)/2;
            let mut line = Line::default();
            line.spans.push(Span::raw(" ".repeat(pad)));
            line.spans.extend(target_spans);
            line.spans.push(Span::raw(" ".repeat(inner_width - pad - total_len_to_show)));
            line
        } else {
            Line::from(target_spans)
        };

        // Second line
        let mut second_content = String::new();
        for i in 0..input_chars.len() {
            if i < lesson_chars.len() && input_chars[i]==lesson_chars[i] {
                second_content.push(' ');
            } else {
                second_content.push(input_chars[i]);
            }
        }
        let second_len = second_content.chars().count();
        let second_padded = if total_len_to_show < inner_width {
            let pad = (inner_width - total_len_to_show)/2;
            let mut s = " ".repeat(pad);
            s.push_str(&second_content);
            let remaining = inner_width - pad - second_len;
            if remaining>0 {
                s.push_str(&" ".repeat(remaining));
            }
            s
        } else {
            let mut s = second_content.clone();
            if s.chars().count()>inner_width {
                s = s.chars().take(inner_width).collect();
            } else {
                while s.chars().count()<inner_width {
                    s.push(' ');
                }
            }
            s
        };
        let second_line = Line::from(vec![
            Span::styled(second_padded, Style::default().add_modifier(Modifier::ITALIC).fg(Color::Gray)),
        ]);

        // Keyboard
        let flat = layout_flat(&display_layout_name);
        let row0_keys = &flat[0..12];
        let row1_keys = &flat[12..23];
        let row2_keys = &flat[23..33];

        let top_box = {
            let mut s = String::from("┌");
            for i in 0..12 {
                s.push_str("───");
                if i!=11 { s.push_str("┬"); } else { s.push_str("┐"); }
            }
            s
        };
        let top_keys_line = {
            let mut s = String::from("│");
            for k in row0_keys {
                s.push_str(&format!(" {} │", k));
            }
            s
        };
        let top_bottom = {
            let mut s = String::from("└");
            for i in 0..12 {
                if i==0 { s.push_str("┬"); } else { s.push_str("┴"); }
                s.push_str("───");
                if i==11 { s.push_str("┘"); }
            }
            s
        };
        let mid_keys_line = {
            let mut s = String::from("│");
            for k in row1_keys {
                s.push_str(&format!(" {} │", k));
            }
            s
        };
        let mid_bottom = {
            let mut s = String::from("└");
            for i in 0..11 {
                if i==0 { s.push_str("┬"); } else { s.push_str("┴"); }
                s.push_str("───");
                if i==10 { s.push_str("┘"); }
            }
            s
        };
        let bot_keys_line = {
            let mut s = String::from("│");
            for k in row2_keys {
                s.push_str(&format!(" {} │", k));
            }
            s
        };
        let bot_bottom = {
            let mut s = String::from("└");
            for i in 0..10 {
                s.push_str("───");
                if i!=9 { s.push_str("┴"); } else { s.push_str("┘"); }
            }
            s
        };
        let ortho_mid_sep = {
            let mut s = String::from("├");
            for i in 0..12 {
                s.push_str("───");
                if i!=11 { s.push_str("┼"); } else { s.push_str("┤"); }
            }
            s
        };
        let ortho_mid_keys = {
            let mut s = String::from("│");
            for k in row1_keys {
                s.push_str(&format!(" {} │", k));
            }
            s.push_str(" △ │");
            s
        };
        let ortho_bot_keys = {
            let mut s = String::from("│");
            for k in row2_keys {
                s.push_str(&format!(" {} │", k));
            }
            s.push_str(" △ │ △ │");
            s
        };
        let ortho_bot_bottom = {
            let mut s = String::from("└");
            for i in 0..12 {
                s.push_str("───");
                if i!=11 { s.push_str("┴"); } else { s.push_str("┘"); }
            }
            s
        };

        terminal.draw(|f| {
            let size = f.size();
            let title = Line::from(vec![
                Span::styled(" Quit ", Style::default().fg(Color::Gray)),
                Span::styled("<esc>", Style::default().add_modifier(Modifier::BOLD).fg(Color::Blue)),
                Span::raw(" "),
            ]);
            let outer = Block::default()
                .borders(Borders::ALL)
                .title(title)
                .title_alignment(Alignment::Right);
            let inner_area = outer.inner(size);
            f.render_widget(outer, size);

            let mut inner_lines: Vec<Line> = Vec::new();
            inner_lines.push(Line::from(vec![
                Span::raw("                                  "),
                Span::styled("ngrrram!", Style::default().add_modifier(Modifier::BOLD)),
                Span::styled("   by winterveil", Style::default().add_modifier(Modifier::ITALIC).fg(Color::Gray)),
                Span::raw("                   "),
            ]));
            inner_lines.push(Line::from("─────────────────────────────────────────────────────────────────────────────"));
            let base = format!("    Lesson #{}", lesson_num);
            let prefix = base + &" ".repeat(50);
            let check_part = format!("✔: {}, ", success_count);
            let cross_part = format!("✘: {}    ", fail_count);
            inner_lines.push(Line::from(vec![
                Span::raw(prefix),
                Span::styled(check_part, Style::default().fg(Color::Green)),
                Span::styled(cross_part, Style::default().fg(Color::Red)),
            ]));
            inner_lines.push(Line::from("─────────────────────────────────────────────────────────────────────────────"));
            inner_lines.push(Line::from(""));
            inner_lines.push(target_line);
            inner_lines.push(second_line);
            inner_lines.push(Line::from(""));

            if !nokb {
                if show_ortho {
                    inner_lines.push(Line::from(format!("{}{}{}", " ".repeat(13), top_box, " ".repeat(15))));
                    inner_lines.push(Line::from(format!("{}{}{}", " ".repeat(13), top_keys_line, " ".repeat(15))));
                    inner_lines.push(Line::from(format!("{}{}{}", " ".repeat(13), ortho_mid_sep, " ".repeat(15))));
                    inner_lines.push(Line::from(format!("{}{}{}", " ".repeat(13), ortho_mid_keys, " ".repeat(15))));
                    inner_lines.push(Line::from(format!("{}{}{}", " ".repeat(13), ortho_mid_sep, " ".repeat(15))));
                    inner_lines.push(Line::from(format!("{}{}{}", " ".repeat(13), ortho_bot_keys, " ".repeat(15))));
                    inner_lines.push(Line::from(format!("{}{}{}", " ".repeat(13), ortho_bot_bottom, " ".repeat(15))));
                } else {
                    inner_lines.push(Line::from(format!("{}{}{}", " ".repeat(13), top_box, " ".repeat(15))));
                    inner_lines.push(Line::from(format!("{}{}{}", " ".repeat(13), top_keys_line, " ".repeat(15))));
                    inner_lines.push(Line::from(format!("{}{}{}", " ".repeat(13), top_bottom, " ".repeat(15))));
                    inner_lines.push(Line::from(format!("{}{}{}", " ".repeat(14), mid_keys_line, " ".repeat(18))));
                    inner_lines.push(Line::from(format!("{}{}{}", " ".repeat(14), mid_bottom, " ".repeat(18))));
                    inner_lines.push(Line::from(format!("{}{}{}", " ".repeat(15), bot_keys_line, " ".repeat(21))));
                    inner_lines.push(Line::from(format!("{}{}{}", " ".repeat(15), bot_bottom, " ".repeat(21))));
                }
                inner_lines.push(Line::from("─────────────────────────────────────────────────────────────────────────────"));
                let avg_wpm = if wpm_history.is_empty() {0} else {wpm_history.iter().sum::<usize>()/wpm_history.len()};
                let last_wpm = wpm_history.last().cloned().unwrap_or(0);
                let avg_acc = if acc_history.is_empty() {0} else {acc_history.iter().sum::<usize>()/acc_history.len()};
                let last_acc = acc_history.last().cloned().unwrap_or(0);
                let wpm_line = format!("  need >= {:3}WPM,   avg. {:3}WPM,   last {:3}WPM                               ", wpm_thresh, avg_wpm, last_wpm);
                let acc_line = format!("  need >= {:3}% Acc, avg. {:3}% Acc, last {:3}% Acc                             ", acc_thresh, avg_acc, last_acc);
                inner_lines.push(Line::from(wpm_line));
                inner_lines.push(Line::from(acc_line));
            } else {
                inner_lines.push(Line::from(""));
                inner_lines.push(Line::from(""));
                inner_lines.push(Line::from("─────────────────────────────────────────────────────────────────────────────"));
                let avg_wpm = if wpm_history.is_empty() {0} else {wpm_history.iter().sum::<usize>()/wpm_history.len()};
                let last_wpm = wpm_history.last().cloned().unwrap_or(0);
                let avg_acc = if acc_history.is_empty() {0} else {acc_history.iter().sum::<usize>()/acc_history.len()};
                let last_acc = acc_history.last().cloned().unwrap_or(0);
                if cat {
                    let wpm_base = format!("  need >= {:3}WPM,   avg. {:3}WPM,   last {:3}WPM", wpm_thresh, avg_wpm, last_wpm);
                    let mut wpm_padded = wpm_base.clone();
                    while wpm_padded.chars().count()<58 {
                        wpm_padded.push(' ');
                    }
                    wpm_padded.push_str("/\\_/\\");
                    while wpm_padded.chars().count()<77 {
                        wpm_padded.push(' ');
                    }
                    inner_lines.push(Line::from(wpm_padded));
                    let acc_base = format!("  need >= {:3}% Acc, avg. {:3}% Acc, last {:3}% Acc", acc_thresh, avg_acc, last_acc);
                    let mut acc_padded = acc_base.clone();
                    while acc_padded.chars().count()<55 {
                        acc_padded.push(' ');
                    }
                    acc_padded.push_str(">(•༝• )<");
                    while acc_padded.chars().count()<77 {
                        acc_padded.push(' ');
                    }
                    inner_lines.push(Line::from(acc_padded));
                    inner_lines.push(Line::from("────────────────────────────────────────────────────────────    |    \\───────"));
                } else {
                    let wpm_line = format!("  need >= {:3}WPM,   avg. {:3}WPM,   last {:3}WPM                               ", wpm_thresh, avg_wpm, last_wpm);
                    let acc_line = format!("  need >= {:3}% Acc, avg. {:3}% Acc, last {:3}% Acc                             ", acc_thresh, avg_acc, last_acc);
                    inner_lines.push(Line::from(wpm_line));
                    inner_lines.push(Line::from(acc_line));
                    inner_lines.push(Line::from("─────────────────────────────────────────────────────────────────────────────"));
                }
            }

            let para = Paragraph::new(inner_lines);
            f.render_widget(para, inner_area);
        }).unwrap();

        if event::poll(Duration::from_millis(50)).unwrap() {
            if let Event::Key(key) = event::read().unwrap() {
                if key.kind != KeyEventKind::Press { continue; }
                match key.code {
                    KeyCode::Esc => break,
                    KeyCode::Backspace => {
                        if !input_buffer.is_empty() {
                            input_buffer.pop();
                            total_keystrokes+=1;
                        }
                    }
                    KeyCode::Enter => {
                        if input_buffer.len() >= current_lesson_full.len() {
                            let elapsed = start_time.map(|s| s.elapsed()).unwrap_or(Duration::from_secs(1));
                            let secs = elapsed.as_secs_f64();
                            let non_space = current_lesson_full.chars().filter(|c| *c!=' ').count() as f64;
                            let words = non_space / 5.0;
                            let wpm = if secs>0.0 { (words / (secs/60.0)) as usize } else { 0 };
                            let acc = if total_keystrokes==0 { 100 } else { ((total_keystrokes - wrong_keystrokes) as f64 / total_keystrokes as f64 * 100.0) as usize };
                            wpm_history.push(wpm);
                            acc_history.push(acc);
                            if wpm >= wpm_thresh && acc >= acc_thresh {
                                success_count+=1;
                            } else {
                                fail_count+=1;
                            }
                            lesson_num+=1;
                            current_lesson_full = generate_lesson(&source_list, combi, rep);
                            input_buffer.clear();
                            total_keystrokes=0;
                            wrong_keystrokes=0;
                            start_time=None;
                        }
                    }
                    KeyCode::Char(c) => {
                        if start_time.is_none() {
                            start_time = Some(Instant::now());
                        }
                        total_keystrokes+=1;
                        let mapped = if let Some(ref map) = emu_mapping {
                            if let Some(&mc) = map.get(&c) {
                                mc
                            } else {
                                c
                            }
                        } else {
                            c
                        };
                        let expected = current_lesson_full.chars().nth(input_buffer.len());
                        if let Some(exp) = expected {
                            if mapped != exp {
                                wrong_keystrokes+=1;
                            }
                        } else {
                            wrong_keystrokes+=1;
                        }
                        input_buffer.push(mapped);
                    }
                    _ => {}
                }
            }
        }
    }

    let _ = terminal.backend_mut().execute(LeaveAlternateScreen);
    let _ = crossterm::terminal::disable_raw_mode();
    let _ = io::stdout().execute(cursor::Show);
}
RS
./compile.sh 2>&1 | tail -n 50
"}

