                wpm_padded.push_str("/\\_/\\");
                while wpm_padded.chars().count()<77 {
                    wpm_padded.push(' ');
                }
                writeln!(out, "│\x1b[38;5;7m{}\x1b[39m│", wpm_padded).unwrap();
                // Actually need proper gray splitting? Original for cat had gray for "need..." parts but also cat part? In earlier ansi for cat nokb, WPM line had gray for need parts and cat part not gray? Let's check: earlier ansi for cat nokb WPM: "\x1b[38;5;7m  need >=  40WPM,   avg. \x1b[39m  0WPM\x1b[38;5;7m,   last\x1b[39m   0WPM                  /\\_/\\        "
                // So cat "/\_/\" is not gray? In that ansi, after last WPM, there were spaces then "/\_/\" but no gray code for cat? The line started with gray, then after avg WPM number reset? Actually structure: gray "  need >=  40WPM,   avg. " then default "  0WPM" then gray ",   last" then default "  0WPM" then many spaces then "/\_/\"? The cat part may be not gray? In capture, after last WPM, there are spaces then "/\_/\" but still within gray? Let's not overcomplicate, we'll just use simple gray splitting similar to normal but with cat appended

                let acc_base = format!("  need >= {:3}% Acc, avg. {:3}% Acc, last {:3}% Acc", acc_thresh, avg_acc, last_acc);
                let mut acc_padded = acc_base.clone();
                while acc_padded.chars().count()<55 {
