            } else {
                target_spans.push(Span::styled(target_char.to_string(), Style::default().add_modifier(Modifier::BOLD)));
            }
        }

        let target_line = if total_len_to_show < inner_width {
            let pad = (inner_width - total_len_to_show)/2;
            let mut line = Line::default();
            line.spans.push(Span::raw(" ".repeat(pad)));
            line.spans.extend(target_spans);
            line.spans.push(Span::raw(" ".repeat(inner_width - pad - total_len_to_show)));
            line
        } else {
            Line::from(target_spans)
        };

        let mut second_content = String::new();
        for i in 0..input_chars.len() {
            if i < lesson_chars.len() && input_chars[i]==lesson_chars[i] {
                second_content.push(' ');
            } else {
                second_content.push(input_chars[i]);
            }
        }
        let second_len = second_content.chars().count();
        let second_padded = if total_len_to_show < inner_width {
            let pad = (inner_width - total_len_to_show)/2;
            let mut s = " ".repeat(pad);
            s.push_str(&second_content);
            let remaining = inner_width - pad - second_len;
            if remaining>0 {
                s.push_str(&" ".repeat(remaining));
            }
            s
        } else {
            let mut s = second_content.clone();
            if s.chars().count()>inner_width {
                s = s.chars().take(inner_width).collect();
            } else {
                while s.chars().count()<inner_width {
                    s.push(' ');
                }
            }
            s
        };
        let second_line = Line::from(vec![
            Span::styled(second_padded, Style::default().add_modifier(Modifier::ITALIC).fg(Color::Gray)),
        ]);

        terminal.draw(|f| {
            let size = f.size();
            let title = Line::from(vec![
                Span::styled(" Quit ", Style::default().fg(Color::Gray)),
                Span::styled("<esc>", Style::default().add_modifier(Modifier::BOLD).fg(Color::Blue)),
                Span::raw(" "),
            ]);
            let outer = Block::default()
                .border_type(BorderType::Rounded)
                .borders(Borders::ALL)
                .title(title)
                .title_alignment(Alignment::Right);
            let inner_area = outer.inner(size);
            f.render_widget(outer, size);

            let mut inner_lines: Vec<Line> = Vec::new();
            inner_lines.push(Line::from(vec![
                Span::raw("                                  "),
                Span::styled("ngrrram!", Style::default().add_modifier(Modifier::BOLD)),
                Span::styled("   by winterveil", Style::default().add_modifier(Modifier::ITALIC).fg(Color::Gray)),
                Span::raw("                   "),
            ]));
            inner_lines.push(Line::from("─────────────────────────────────────────────────────────────────────────────"));
            let base = format!("    Lesson #{}", lesson_num);
            let prefix = base + &" ".repeat(50);
            let check_part = format!("✔: {}, ", success_count);
            let cross_part = format!("✘: {}    ", fail_count);
            inner_lines.push(Line::from(vec![
                Span::raw(prefix),
                Span::styled(check_part, Style::default().fg(Color::Green)),
                Span::styled(cross_part, Style::default().fg(Color::Red)),
            ]));
            inner_lines.push(Line::from("─────────────────────────────────────────────────────────────────────────────"));
            inner_lines.push(Line::from(""));
            inner_lines.push(target_line);
            inner_lines.push(second_line);
            inner_lines.push(Line::from(""));

            if !nokb {
                if show_ortho {
                    inner_lines.push(Line::from(format!("{}{}{}", " ".repeat(13), top_box, " ".repeat(15))));
                    inner_lines.push(Line::from(format!("{}{}{}", " ".repeat(13), top_keys_line, " ".repeat(15))));
                    inner_lines.push(Line::from(format!("{}{}{}", " ".repeat(13), ortho_mid_sep, " ".repeat(15))));
                    inner_lines.push(Line::from(format!("{}{}{}", " ".repeat(13), ortho_mid_keys, " ".repeat(15))));
                    inner_lines.push(Line::from(format!("{}{}{}", " ".repeat(13), ortho_mid_sep, " ".repeat(15))));
                    inner_lines.push(Line::from(format!("{}{}{}", " ".repeat(13), ortho_bot_keys, " ".repeat(15))));
                    inner_lines.push(Line::from(format!("{}{}{}", " ".repeat(13), ortho_bot_bottom, " ".repeat(15))));
                } else {
                    inner_lines.push(Line::from(format!("{}{}{}", " ".repeat(13), top_box, " ".repeat(15))));
                    inner_lines.push(Line::from(format!("{}{}{}", " ".repeat(13), top_keys_line, " ".repeat(15))));
                    inner_lines.push(Line::from(format!("{}{}{}", " ".repeat(13), top_bottom, " ".repeat(15))));
                    inner_lines.push(Line::from(format!("{}{}{}", " ".repeat(14), mid_keys_line, " ".repeat(18))));
                    inner_lines.push(Line::from(format!("{}{}{}", " ".repeat(14), mid_bottom, " ".repeat(18))));
                    inner_lines.push(Line::from(format!("{}{}{}", " ".repeat(15), bot_keys_line, " ".repeat(21))));
                    inner_lines.push(Line::from(format!("{}{}{}", " ".repeat(15), bot_bottom, " ".repeat(21))));
                }
                inner_lines.push(Line::from("─────────────────────────────────────────────────────────────────────────────"));
                let avg_wpm = if wpm_history.is_empty() {0} else {wpm_history.iter().sum::<usize>()/wpm_history.len()};
                let last_wpm = wpm_history.last().cloned().unwrap_or(0);
                let avg_acc = if acc_history.is_empty() {0} else {acc_history.iter().sum::<usize>()/acc_history.len()};
                let last_acc = acc_history.last().cloned().unwrap_or(0);
                inner_lines.push(Line::from(vec![
                    Span::styled(format!("  need >= {:3}WPM,   avg. ", wpm_thresh), Style::default().fg(Color::Gray)),
                    Span::raw(format!("{:3}WPM", avg_wpm)),
                    Span::styled(",   last", Style::default().fg(Color::Gray)),
                    Span::raw(format!("{:3}WPM                               ", last_wpm)),
                ]));
                inner_lines.push(Line::from(vec![
                    Span::styled(format!("  need >= {:3}% Acc, avg. ", acc_thresh), Style::default().fg(Color::Gray)),
                    Span::raw(format!("{:3}% Acc", avg_acc)),
                    Span::styled(", last", Style::default().fg(Color::Gray)),
                    Span::raw(format!("{:3}% Acc                             ", last_acc)),
                ]));
            } else {
                inner_lines.push(Line::from(""));
                inner_lines.push(Line::from(""));
                inner_lines.push(Line::from("─────────────────────────────────────────────────────────────────────────────"));
                let avg_wpm = if wpm_history.is_empty() {0} else {wpm_history.iter().sum::<usize>()/wpm_history.len()};
                let last_wpm = wpm_history.last().cloned().unwrap_or(0);
                let avg_acc = if acc_history.is_empty() {0} else {acc_history.iter().sum::<usize>()/acc_history.len()};
                let last_acc = acc_history.last().cloned().unwrap_or(0);
                if cat {
                    inner_lines.push(Line::from(vec![
                        Span::styled(format!("  need >= {:3}WPM,   avg. ", wpm_thresh), Style::default().fg(Color::Gray)),
                        Span::raw(format!("{:3}WPM", avg_wpm)),
                        Span::styled(",   last", Style::default().fg(Color::Gray)),
                        Span::raw(format!("{:3}WPM                  /\\_/\\        ", last_wpm)),
