                    inner_lines.push(Line::from(vec![
                        Span::styled(format!("  need >= {:3}% Acc, avg. ", acc_thresh), Style::default().fg(Color::Gray)),
                        Span::raw(format!("{:3}% Acc", avg_acc)),
                        Span::styled(", last", Style::default().fg(Color::Gray)),
                        Span::raw(format!("{:3}% Acc               >(•༝• )<      ", last_acc)),
                    ]));
                    inner_lines.push(Line::from("────────────────────────────────────────────────────────────    |    \\───────"));
                } else {
                    inner_lines.push(Line::from(vec![
                        Span::styled(format!("  need >= {:3}WPM,   avg. ", wpm_thresh), Style::default().fg(Color::Gray)),
                        Span::raw(format!("{:3}WPM", avg_wpm)),
                        Span::styled(",   last", Style::default().fg(Color::Gray)),
                        Span::raw(format!("{:3}WPM                               ", last_wpm)),
                    ]));
                    inner_lines.push(Line::from(vec![
                        Span::styled(format!("  need >= {:3}% Acc, avg. ", acc_thresh), Style::default().fg(Color::Gray)),
                        Span::raw(format!("{:3}% Acc", avg_acc)),
                        Span::styled(", last", Style::default().fg(Color::Gray)),
                        Span::raw(format!("{:3}% Acc                             ", last_acc)),
                    ]));
                    inner_lines.push(Line::from("─────────────────────────────────────────────────────────────────────────────"));
                }
            }

            let para = Paragraph::new(inner_lines);
            f.render_widget(para, inner_area);
        }).unwrap();

        if event::poll(Duration::from_millis(50)).unwrap() {
            if let Event::Key(key) = event::read().unwrap() {
                if key.kind != KeyEventKind::Press { continue; }
                match key.code {
                    KeyCode::Esc => break,
                    KeyCode::Backspace => {
                        if !input_buffer.is_empty() {
                            input_buffer.pop();
                            total_keystrokes+=1;
                        }
                    }
                    KeyCode::Enter => {
                        if input_buffer.len() >= current_lesson_full.len() {
                            let elapsed = start_time.map(|s| s.elapsed()).unwrap_or(Duration::from_secs(1));
                            let secs = elapsed.as_secs_f64();
                            let non_space = current_lesson_full.chars().filter(|c| *c!=' ').count() as f64;
                            let words = non_space / 5.0;
                            let wpm = if secs>0.0 { (words / (secs/60.0)) as usize } else { 0 };
                            let acc = if total_keystrokes==0 { 100 } else { ((total_keystrokes - wrong_keystrokes) as f64 / total_keystrokes as f64 * 100.0) as usize };
                            wpm_history.push(wpm);
                            acc_history.push(acc);
                            if wpm >= wpm_thresh && acc >= acc_thresh {
                                success_count+=1;
                            } else {
                                fail_count+=1;
                            }
                            lesson_num+=1;
                            current_lesson_full = generate_lesson(&source_list, combi, rep);
                            input_buffer.clear();
                            total_keystrokes=0;
                            wrong_keystrokes=0;
                            start_time=None;
                        }
                    }
                    KeyCode::Char(c) => {
                        if start_time.is_none() {
                            start_time = Some(Instant::now());
                        }
                        total_keystrokes+=1;
                        let mapped = if let Some(ref map) = emu_mapping {
                            if let Some(&mc) = map.get(&c) {
                                mc
                            } else {
                                c
                            }
                        } else {
                            c
                        };
                        let expected = current_lesson_full.chars().nth(input_buffer.len());
                        if let Some(exp) = expected {
                            if mapped != exp {
                                wrong_keystrokes+=1;
                            }
                        } else {
                            wrong_keystrokes+=1;
                        }
                        input_buffer.push(mapped);
                    }
                    _ => {}
                }
            }
        }
    }

    let mut out = io::stdout();
    let _ = out.execute(LeaveAlternateScreen);
    let _ = crossterm::terminal::disable_raw_mode();
    let _ = out.execute(cursor::Show);
}
RS
./compile.sh 2>&1 | tail -n 20
./executable --help 2>&1
"}

