    let flat = layout_flat(&display_layout_name);
    let row0_keys = &flat[0..12];
    let row1_keys = &flat[12..23];
    let row2_keys = &flat[23..33];

    let top_box = {
        let mut s = String::from("┌");
        for i in 0..12 {
            s.push_str("───");
            if i!=11 { s.push_str("┬"); } else { s.push_str("┐"); }
        }
        s
    };
    let top_keys_line = {
        let mut s = String::from("│");
        for k in row0_keys {
            s.push_str(&format!(" {} │", k));
        }
        s
    };
    let top_bottom = {
        let mut s = String::from("└");
        for i in 0..12 {
            if i==0 { s.push_str("┬"); } else { s.push_str("┴"); }
            s.push_str("───");
            if i==11 { s.push_str("┘"); }
        }
        s
    };
    let mid_keys_line = {
        let mut s = String::from("│");
        for k in row1_keys {
            s.push_str(&format!(" {} │", k));
        }
        s
    };
    let mid_bottom = {
        let mut s = String::from("└");
        for i in 0..11 {
            if i==0 { s.push_str("┬"); } else { s.push_str("┴"); }
            s.push_str("───");
            if i==10 { s.push_str("┘"); }
        }
        s
    };
    let bot_keys_line = {
        let mut s = String::from("│");
        for k in row2_keys {
            s.push_str(&format!(" {} │", k));
        }
