        let second_len = second_content.chars().count();
        let second_padded = if total_len_to_show < inner_width {
            let pad = (inner_width - total_len_to_show)/2;
            let mut s = " ".repeat(pad);
            s.push_str(&second_content);
            let remaining = inner_width - pad - second_len;
            if remaining>0 {
                s.push_str(&" ".repeat(remaining));
            }
            s
        } else {
            let mut s = second_content.clone();
            if s.chars().count()>inner_width {
                s = s.chars().take(inner_width).collect();
            } else {
                while s.chars().count()<inner_width {
                    s.push(' ');
                }
