                } else {
                    eprintln!("error: a value is required for '--combi <1-200>' but none was supplied\n\nFor more information, try '--help'.\n");
                    std::process::exit(2);
                }
            }
            "-r" | "--rep" => {
                if let Some(v) = args_iter.next() {
                    match v.parse::<usize>() {
                        Ok(val) if val>=1 && val<=200 => rep = val,
                        _ => {
                            eprintln!("Invalid argument for rep. Use a number between 1 and 200.");
                            std::process::exit(1);
                        }
