        for k in row2_keys {
            s.push_str(&format!(" {} │", k));
        }
        s.push_str(" △ │ △ │");
        s
    };
    let ortho_bot_bottom = {
        let mut s = String::from("└");
        for i in 0..12 {
            s.push_str("───");
            if i!=11 { s.push_str("┴"); } else { s.push_str("┘"); }
        }
        s
    };

    loop {
        let inner_width = 77usize;
        let lesson_chars: Vec<char> = current_lesson_full.chars().collect();
        let input_chars: Vec<char> = input_buffer.chars().collect();
        let total_len_to_show = std::cmp::min(inner_width, std::cmp::max(lesson_chars.len(), input_chars.len()));

        let mut target_ansi = String::new();
        target_ansi.push_str("\x1b[1m");
        for i in 0..total_len_to_show {
            let target_char = if i < lesson_chars.len() { lesson_chars[i] } else { '•' };
            if i < input_chars.len() {
                if i < lesson_chars.len() {
                    if input_chars[i] == lesson_chars[i] {
                        target_ansi.push_str(&format!("\x1b[38;5;2m{}\x1b[39m", target_char));
                    } else {
                        if lesson_chars[i] == ' ' {
                            target_ansi.push_str("\x1b[38;5;1m•\x1b[39m");
                        } else {
                            target_ansi.push_str(&format!("\x1b[38;5;1m{}\x1b[39m", target_char));
                        }
                    }
                } else {
                    target_ansi.push_str("\x1b[38;5;1m•\x1b[39m");
                }
            } else {
                target_ansi.push_str(&target_char.to_string());
            }
        }
        target_ansi.push_str("\x1b[0m\x1b[39m\x1b[49m");

        let target_line_str = if total_len_to_show < inner_width {
            let pad = (inner_width - total_len_to_show)/2;
            format!("│{}{}{}│", " ".repeat(pad), target_ansi, " ".repeat(inner_width - pad - total_len_to_show))
        } else {
            format!("│{}│", target_ansi)
        };

        let mut second_content = String::new();
        for i in 0..input_chars.len() {
            if i < lesson_chars.len() && input_chars[i]==lesson_chars[i] {
                second_content.push(' ');
            } else {
                second_content.push(input_chars[i]);
            }
        }
        let second_len = second_content.chars().count();
        let second_padded = if total_len_to_show < inner_width {
            let pad = (inner_width - total_len_to_show)/2;
            let mut s = " ".repeat(pad);
            s.push_str(&second_content);
            let remaining = inner_width - pad - second_len;
            if remaining>0 {
                s.push_str(&" ".repeat(remaining));
