    let mut stdout = io::stdout();
    let _ = stdout.execute(EnterAlternateScreen);
    let _ = stdout.execute(cursor::Hide);
    let _ = crossterm::terminal::enable_raw_mode();

    let mut lesson_num = 1usize;
    let mut success_count = 0usize;
    let mut fail_count = 0usize;
    let mut wpm_history: Vec<usize> = Vec::new();
    let mut acc_history: Vec<usize> = Vec::new();

    let mut current_lesson_full = generate_lesson(&source_list, combi, rep);
    let mut input_buffer: String = String::new();
    let mut total_keystrokes: usize = 0;
    let mut wrong_keystrokes: usize = 0;
    let mut start_time: Option<Instant> = None;

    let display_layout_name = if !emu_out.is_empty() { emu_out.clone() } else { "qwerty".to_string() };
    let flat = layout_flat(&display_layout_name);
    let row0_keys = &flat[0..12];
    let row1_keys = &flat[12..23];
    let row2_keys = &flat[23..33];

    let top_box = {
        let mut s = String::from("┌");
