        s
    };
    let top_bottom = {
        let mut s = String::from("└");
        for i in 0..12 {
            if i==0 { s.push_str("┬"); } else { s.push_str("┴"); }
            s.push_str("───");
            if i==11 { s.push_str("┘"); }
        }
        s
    };
    let mid_keys_line = {
        let mut s = String::from("│");
        for k in row1_keys {
            s.push_str(&format!(" {} │", k));
        }
        s
    };
    let mid_bottom = {
        let mut s = String::from("└");
