    let mut emu_out = String::new();
    let mut show_ortho = false;
    let mut nokb = false;
    let mut cat = false;

    let help_text = "Usage: executable [OPTIONS]\n\nOptions:\n  -n, --n <2|3|4|w|file>  use bi-(2), tri-(3), tetragrams(4), (w)ords or comma separated wordlist file. [default: 2]\n  -t, --top <1-200>       use the top X ngrams ordered by usage. [default: 50]\n  -c, --combi <1-200>     how many different ngrams to use in a single lesson. [default: 2]\n  -r, --rep <number>      how often to repeat *each* different ngram in a lesson. [default: 3]\n  -w, --wpm <number>      the wpm threshold at which the lesson is considered a success. [default: 40]\n  -a, --acc <0-100>       the accuracy in percent at which the lesson is considered a success. [default: 94]\n      --emu-in <layout>   your current keyboard layout. only needed if you want to emulate a different layout. see docs for supported layouts. [default: ]\n      --emu-out <layout>  the layout you want to emulate. only needed if you want to emulate a different layout. see docs for supported layouts. [default: ]\n      --show-ortho        show keyboard in ortholinear format\n      --nokb              pass this flag to disable the keyboard layout display.\n      --cat               the most important flag. don't practice alone.\n  -h, --help              Print help\n";

    while let Some(arg) = args_iter.next() {
        match arg.as_str() {
            "-h" | "--help" => {
                print!("{}", help_text);
                return;
            }
            "-n" | "--n" => {
                if let Some(v) = args_iter.next() {
                    n_arg = v.clone();
                } else {
                    eprintln!("error: a value is required for '-n <2|3|4|w|file>' but none was supplied\n\nFor more information, try '--help'.\n");
                    std::process::exit(2);
                }
            }
            "-t" | "--top" => {
                if let Some(v) = args_iter.next() {
                    match v.parse::<usize>() {
                        Ok(val) if val>=1 && val<=200 => top = val,
                        _ => {
                            eprintln!("Invalid argument for top. Use a number between 1 and 200.");
                            std::process::exit(1);
                        }
                    }
                } else {
                    eprintln!("error: a value is required for '--top <1-200>' but none was supplied\n\nFor more information, try '--help'.\n");
                    std::process::exit(2);
                }
            }
            "-c" | "--combi" => {
                if let Some(v) = args_iter.next() {
                    match v.parse::<usize>() {
                        Ok(val) if val>=1 && val<=200 => combi = val,
                        _ => {
                            eprintln!("Invalid argument for combi. Use a number between 1 and 200.");
                            std::process::exit(1);
                        }
                    }
                } else {
                    eprintln!("error: a value is required for '--combi <1-200>' but none was supplied\n\nFor more information, try '--help'.\n");
                    std::process::exit(2);
                }
            }
            "-r" | "--rep" => {
                if let Some(v) = args_iter.next() {
                    match v.parse::<usize>() {
                        Ok(val) if val>=1 && val<=200 => rep = val,
                        _ => {
                            eprintln!("Invalid argument for rep. Use a number between 1 and 200.");
                            std::process::exit(1);
                        }
                    }
                } else {
                    eprintln!("error: a value is required for '--rep <number>' but none was supplied\n\nFor more information, try '--help'.\n");
                    std::process::exit(2);
                }
            }
            "-w" | "--wpm" => {
                if let Some(v) = args_iter.next() {
                    match v.parse::<usize>() {
                        Ok(val) if val>=1 && val<=200 => wpm_thresh = val,
                        _ => {
                            eprintln!("Invalid argument for wpm. Use a number between 1 and 200.");
                            std::process::exit(1);
                        }
                    }
                } else {
                    eprintln!("error: a value is required for '--wpm <number>' but none was supplied\n\nFor more information, try '--help'.\n");
                    std::process::exit(2);
                }
            }
            "-a" | "--acc" => {
                if let Some(v) = args_iter.next() {
                    match v.parse::<usize>() {
                        Ok(val) if val<=100 => acc_thresh = val,
                        _ => {
                            eprintln!("Invalid argument for acc. Use a number between 0 and 100.");
                            std::process::exit(1);
                        }
                    }
                } else {
                    eprintln!("error: a value is required for '--acc <0-100>' but none was supplied\n\nFor more information, try '--help'.\n");
                    std::process::exit(2);
                }
            }
            "--emu-in" => {
                if let Some(v) = args_iter.next() {
                    emu_in = v.clone();
                } else {
                    eprintln!("error: a value is required for '--emu-in <layout>' but none was supplied\n\nFor more information, try '--help'.\n");
                    std::process::exit(2);
                }
            }
            "--emu-out" => {
                if let Some(v) = args_iter.next() {
                    emu_out = v.clone();
                } else {
                    eprintln!("error: a value is required for '--emu-out <layout>' but none was supplied\n\nFor more information, try '--help'.\n");
                    std::process::exit(2);
                }
            }
            "--show-ortho" => { show_ortho = true; }
            "--nokb" => { nokb = true; }
            "--cat" => { cat = true; }
            _ if arg.starts_with('-') && arg.contains('=') => {
                let parts: Vec<&str> = arg.splitn(2, '=').collect();
                let key = parts[0];
                let val = parts[1];
                match key {
                    "-n" | "--n" => n_arg = val.to_string(),
                    "-t" | "--top" => {
                        match val.parse::<usize>() {
                            Ok(v) if v>=1 && v<=200 => top=v,
                            _ => { eprintln!("Invalid argument for top. Use a number between 1 and 200."); std::process::exit(1); }
                        }
                    }
                    "-c" | "--combi" => {
                        match val.parse::<usize>() {
                            Ok(v) if v>=1 && v<=200 => combi=v,
                            _ => { eprintln!("Invalid argument for combi. Use a number between 1 and 200."); std::process::exit(1); }
                        }
                    }
                    "-r" | "--rep" => {
                        match val.parse::<usize>() {
                            Ok(v) if v>=1 && v<=200 => rep=v,
                            _ => { eprintln!("Invalid argument for rep. Use a number between 1 and 200."); std::process::exit(1); }
                        }
                    }
                    "-w" | "--wpm" => {
                        match val.parse::<usize>() {
                            Ok(v) if v>=1 && v<=200 => wpm_thresh=v,
                            _ => { eprintln!("Invalid argument for wpm. Use a number between 1 and 200."); std::process::exit(1); }
                        }
                    }
                    "-a" | "--acc" => {
                        match val.parse::<usize>() {
                            Ok(v) if v<=100 => acc_thresh=v,
                            _ => { eprintln!("Invalid argument for acc. Use a number between 0 and 100."); std::process::exit(1); }
                        }
                    }
                    "--emu-in" => emu_in = val.to_string(),
                    "--emu-out" => emu_out = val.to_string(),
                    _ => {
                        eprintln!("error: unexpected argument '{}' found\n\nUsage: executable [OPTIONS]\n\nFor more information, try '--help'.\n", arg);
                        std::process::exit(2);
                    }
                }
            }
            _ => {
                eprintln!("error: unexpected argument '{}' found\n\nUsage: executable [OPTIONS]\n\nFor more information, try '--help'.\n", arg);
                std::process::exit(2);
            }
        }
    }

    if (!emu_in.is_empty() && emu_out.is_empty()) || (emu_in.is_empty() && !emu_out.is_empty()) {
        eprintln!("You need to specify both emu_in and emu_out.");
        std::process::exit(1);
    }

    let source_list: Vec<String> = if n_arg == "2" {
        let t = std::cmp::min(top, BIGRAMS.len());
        BIGRAMS[..t].iter().map(|s| s.to_string()).collect()
    } else if n_arg == "3" {
        let t = std::cmp::min(top, TRIGRAMS.len());
        TRIGRAMS[..t].iter().map(|s| s.to_string()).collect()
    } else if n_arg == "4" {
        let t = std::cmp::min(top, TETRAGRAMS.len());
        TETRAGRAMS[..t].iter().map(|s| s.to_string()).collect()
    } else if n_arg == "w" {
        let t = std::cmp::min(top, WORDS.len());
        WORDS[..t].iter().map(|s| s.to_string()).collect()
    } else {
        match fs::read_to_string(&n_arg) {
            Ok(content) => {
                let mut list: Vec<String> = Vec::new();
                for part in content.split(',') {
                    let trimmed = part.trim();
                    if !trimmed.is_empty() {
                        list.push(trimmed.to_string());
                    }
                }
                if list.is_empty() {
                    eprintln!("thread 'main' panicked at src/game.rs:18:45:\ncalled `Option::unwrap()` on a `None` value\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace");
                    std::process::exit(101);
                }
                let t = std::cmp::min(top, list.len());
                list[..t].to_vec()
            }
            Err(_) => {
                eprintln!("File not found: {}", n_arg);
                std::process::exit(1);
            }
        }
    };

    let emu_mapping: Option<HashMap<char, char>> = if !emu_in.is_empty() && !emu_out.is_empty() {
        Some(build_mapping(&emu_in, &emu_out))
    } else {
        None
    };

    let mut stdout = io::stdout();
    let _ = stdout.execute(EnterAlternateScreen);
    let _ = stdout.execute(cursor::Hide);
    let _ = crossterm::terminal::enable_raw_mode();

    let mut lesson_num = 1usize;
    let mut success_count = 0usize;
    let mut fail_count = 0usize;
    let mut wpm_history: Vec<usize> = Vec::new();
    let mut acc_history: Vec<usize> = Vec::new();

    let mut current_lesson_full = generate_lesson(&source_list, combi, rep);
    let mut input_buffer: String = String::new();
    let mut total_keystrokes: usize = 0;
    let mut wrong_keystrokes: usize = 0;
    let mut start_time: Option<Instant> = None;

    let display_layout_name = if !emu_out.is_empty() { emu_out.clone() } else { "qwerty".to_string() };
    let flat = layout_flat(&display_layout_name);
    let row0_keys = &flat[0..12];
    let row1_keys = &flat[12..23];
    let row2_keys = &flat[23..33];

    let top_box = {
        let mut s = String::from("┌");
        for i in 0..12 {
            s.push_str("───");
            if i!=11 { s.push_str("┬"); } else { s.push_str("┐"); }
        }
        s
    };
    let top_keys_line = {
        let mut s = String::from("│");
        for k in row0_keys {
            s.push_str(&format!(" {} │", k));
        }
        s
    };
    let top_bottom = {
        let mut s = String::from("└");
        for i in 0..12 {
            if i==0 { s.push_str("┬"); } else { s.push_str("┴"); }
            s.push_str("───");
            if i==11 { s.push_str("┘"); }
        }
        s
    };
    let mid_keys_line = {
        let mut s = String::from("│");
        for k in row1_keys {
            s.push_str(&format!(" {} │", k));
        }
        s
    };
    let mid_bottom = {
        let mut s = String::from("└");
        for i in 0..11 {
            if i==0 { s.push_str("┬"); } else { s.push_str("┴"); }
            s.push_str("───");
            if i==10 { s.push_str("┘"); }
        }
        s
    };
    let bot_keys_line = {
        let mut s = String::from("│");
        for k in row2_keys {
            s.push_str(&format!(" {} │", k));
        }
        s
    };
    let bot_bottom = {
        let mut s = String::from("└");
        for i in 0..10 {
            s.push_str("───");
            if i!=9 { s.push_str("┴"); } else { s.push_str("┘"); }
        }
        s
    };
    let ortho_mid_sep = {
        let mut s = String::from("├");
        for i in 0..12 {
            s.push_str("───");
            if i!=11 { s.push_str("┼"); } else { s.push_str("┤"); }
        }
        s
    };
    let ortho_mid_keys = {
        let mut s = String::from("│");
        for k in row1_keys {
            s.push_str(&format!(" {} │", k));
        }
        s.push_str(" △ │");
        s
    };
    let ortho_bot_keys = {
        let mut s = String::from("│");
        for k in row2_keys {
            s.push_str(&format!(" {} │", k));
        }
        s.push_str(" △ │ △ │");
        s
    };
    let ortho_bot_bottom = {
        let mut s = String::from("└");
        for i in 0..12 {
            s.push_str("───");
            if i!=11 { s.push_str("┴"); } else { s.push_str("┘"); }
        }
        s
    };

    loop {
        let inner_width = 77usize;
        let lesson_chars: Vec<char> = current_lesson_full.chars().collect();
        let input_chars: Vec<char> = input_buffer.chars().collect();
        let total_len_to_show = std::cmp::min(inner_width, std::cmp::max(lesson_chars.len(), input_chars.len()));

        let mut target_ansi = String::new();
        target_ansi.push_str("\x1b[1m");
        for i in 0..total_len_to_show {
            let target_char = if i < lesson_chars.len() { lesson_chars[i] } else { '•' };
            if i < input_chars.len() {
                if i < lesson_chars.len() {
                    if input_chars[i] == lesson_chars[i] {
                        target_ansi.push_str(&format!("\x1b[38;5;2m{}\x1b[39m", target_char));
                    } else {
                        if lesson_chars[i] == ' ' {
                            target_ansi.push_str("\x1b[38;5;1m•\x1b[39m");
                        } else {
                            target_ansi.push_str(&format!("\x1b[38;5;1m{}\x1b[39m", target_char));
                        }
                    }
                } else {
                    target_ansi.push_str("\x1b[38;5;1m•\x1b[39m");
                }
            } else {
                target_ansi.push_str(&target_char.to_string());
            }
        }
        target_ansi.push_str("\x1b[0m\x1b[39m\x1b[49m");

        let target_line_str = if total_len_to_show < inner_width {
            let pad = (inner_width - total_len_to_show)/2;
            format!("│{}{}{}│", " ".repeat(pad), target_ansi, " ".repeat(inner_width - pad - total_len_to_show))
        } else {
            format!("│{}│", target_ansi)
        };

        let mut second_content = String::new();
        for i in 0..input_chars.len() {
            if i < lesson_chars.len() && input_chars[i]==lesson_chars[i] {
                second_content.push(' ');
            } else {
                second_content.push(input_chars[i]);
            }
        }
        let second_len = second_content.chars().count();
        let second_padded = if total_len_to_show < inner_width {
            let pad = (inner_width - total_len_to_show)/2;
            let mut s = " ".repeat(pad);
            s.push_str(&second_content);
            let remaining = inner_width - pad - second_len;
            if remaining>0 {
                s.push_str(&" ".repeat(remaining));
            }
            s
        } else {
            let mut s = second_content.clone();
            if s.chars().count()>inner_width {
                s = s.chars().take(inner_width).collect();
            } else {
                while s.chars().count()<inner_width {
                    s.push(' ');
                }
            }
            s
        };
        let second_line_str = format!("│\x1b[3m\x1b[38;5;7m{}\x1b[0m\x1b[39m\x1b[49m│", second_padded);

        let avg_wpm = if wpm_history.is_empty() {0} else {wpm_history.iter().sum::<usize>()/wpm_history.len()};
        let last_wpm = wpm_history.last().cloned().unwrap_or(0);
        let avg_acc = if acc_history.is_empty() {0} else {acc_history.iter().sum::<usize>()/acc_history.len()};
        let last_acc = acc_history.last().cloned().unwrap_or(0);

        let mut out = io::stdout();
        let _ = out.execute(crossterm::terminal::Clear(crossterm::terminal::ClearType::All));
        let _ = out.execute(cursor::MoveTo(0,0));

        write!(out, "╭{} Quit \x1b[1m\x1b[38;5;4m<esc> \x1b[0m\x1b[39m\x1b[49m╮\r\n", "─".repeat(65)).unwrap();
        write!(out, "│                   \x1b[1m               ngrrram!\x1b[0;3m\x1b[38;5;7m\x1b[49m   by winterveil\x1b[0m\x1b[39m\x1b[49m                   │\r\n").unwrap();
        write!(out, "│─────────────────────────────────────────────────────────────────────────────│\r\n").unwrap();
        let base = format!("    Lesson #{}", lesson_num);
        let prefix = base + &" ".repeat(50);
        let check_part = format!("✔: {}, ", success_count);
        let cross_part = format!("✘: {}    ", fail_count);
        write!(out, "│{}\x1b[38;5;2m{}\x1b[38;5;1m{}\x1b[39m│\r\n", prefix, check_part, cross_part).unwrap();
        write!(out, "│─────────────────────────────────────────────────────────────────────────────│\r\n").unwrap();
        write!(out, "│{:77}│\r\n", "").unwrap();
        write!(out, "{}\r\n", target_line_str).unwrap();
        write!(out, "{}\r\n", second_line_str).unwrap();
        write!(out, "│{:77}│\r\n", "").unwrap();

        if !nokb {
            if show_ortho {
                write!(out, "│\x1b[38;5;7m{}{}{}\x1b[39m│\r\n", " ".repeat(13), top_box, " ".repeat(15)).unwrap();
                write!(out, "│\x1b[38;5;7m{}{}{}\x1b[39m│\r\n", " ".repeat(13), top_keys_line, " ".repeat(15)).unwrap();
                write!(out, "│\x1b[38;5;7m{}{}{}\x1b[39m│\r\n", " ".repeat(13), ortho_mid_sep, " ".repeat(15)).unwrap();
                write!(out, "│\x1b[38;5;7m{}{}{}\x1b[39m│\r\n", " ".repeat(13), ortho_mid_keys, " ".repeat(15)).unwrap();
                write!(out, "│\x1b[38;5;7m{}{}{}\x1b[39m│\r\n", " ".repeat(13), ortho_mid_sep, " ".repeat(15)).unwrap();
                write!(out, "│\x1b[38;5;7m{}{}{}\x1b[39m│\r\n", " ".repeat(13), ortho_bot_keys, " ".repeat(15)).unwrap();
                write!(out, "│\x1b[38;5;7m{}{}{}\x1b[39m│\r\n", " ".repeat(13), ortho_bot_bottom, " ".repeat(15)).unwrap();
            } else {
                write!(out, "│\x1b[38;5;7m{}{}{}\x1b[39m│\r\n", " ".repeat(13), top_box, " ".repeat(15)).unwrap();
                write!(out, "│\x1b[38;5;7m{}{}{}\x1b[39m│\r\n", " ".repeat(13), top_keys_line, " ".repeat(15)).unwrap();
                write!(out, "│\x1b[38;5;7m{}{}{}\x1b[39m│\r\n", " ".repeat(13), top_bottom, " ".repeat(15)).unwrap();
                write!(out, "│\x1b[38;5;7m{}{}{}\x1b[39m│\r\n", " ".repeat(14), mid_keys_line, " ".repeat(18)).unwrap();
                write!(out, "│\x1b[38;5;7m{}{}{}\x1b[39m│\r\n", " ".repeat(14), mid_bottom, " ".repeat(18)).unwrap();
                write!(out, "│\x1b[38;5;7m{}{}{}\x1b[39m│\r\n", " ".repeat(15), bot_keys_line, " ".repeat(21)).unwrap();
                write!(out, "│\x1b[38;5;7m{}{}{}\x1b[39m│\r\n", " ".repeat(15), bot_bottom, " ".repeat(21)).unwrap();
            }
            writeln!(out, "│─────────────────────────────────────────────────────────────────────────────│\r").unwrap();
            writeln!(out, "│\x1b[38;5;7m  need >= {:3}WPM,   avg. \x1b[39m{:3}WPM\x1b[38;5;7m,   last\x1b[39m{:3}WPM                               │\r", wpm_thresh, avg_wpm, last_wpm).unwrap();
            writeln!(out, "│\x1b[38;5;7m  need >= {:3}% Acc, avg. \x1b[39m{:3}% Acc\x1b[38;5;7m, last\x1b[39m{:3}% Acc                             │\r", acc_thresh, avg_acc, last_acc).unwrap();
            writeln!(out, "╰─────────────────────────────────────────────────────────────────────────────╯\r").unwrap();
        } else {
            writeln!(out, "│─────────────────────────────────────────────────────────────────────────────│\r").unwrap();
            if cat {
                writeln!(out, "│\x1b[38;5;7m  need >= {:3}WPM,   avg. \x1b[39m{:3}WPM\x1b[38;5;7m,   last\x1b[39m{:3}WPM                  /\\_/\\        │\r", wpm_thresh, avg_wpm, last_wpm).unwrap();
                writeln!(out, "│\x1b[38;5;7m  need >= {:3}% Acc, avg. \x1b[39m{:3}% Acc\x1b[38;5;7m, last\x1b[39m{:3}% Acc               >(•༝• )<      │\r", acc_thresh, avg_acc, last_acc).unwrap();
                writeln!(out, "╰────────────────────────────────────────────────────────────    |    \\───────╯\r").unwrap();
            } else {
                writeln!(out, "│\x1b[38;5;7m  need >= {:3}WPM,   avg. \x1b[39m{:3}WPM\x1b[38;5;7m,   last\x1b[39m{:3}WPM                               │\r", wpm_thresh, avg_wpm, last_wpm).unwrap();
                writeln!(out, "│\x1b[38;5;7m  need >= {:3}% Acc, avg. \x1b[39m{:3}% Acc\x1b[38;5;7m, last\x1b[39m{:3}% Acc                             │\r", acc_thresh, avg_acc, last_acc).unwrap();
                writeln!(out, "╰─────────────────────────────────────────────────────────────────────────────╯\r").unwrap();
            }
        }

        out.flush().unwrap();

        if event::poll(Duration::from_millis(50)).unwrap() {
            if let Event::Key(key) = event::read().unwrap() {
                if key.kind != KeyEventKind::Press { continue; }
                match key.code {
                    KeyCode::Esc => break,
                    KeyCode::Backspace => {
                        if !input_buffer.is_empty() {
                            input_buffer.pop();
                            total_keystrokes+=1;
                        }
                    }
                    KeyCode::Enter => {
                        if input_buffer.len() >= current_lesson_full.len() {
                            let elapsed = start_time.map(|s| s.elapsed()).unwrap_or(Duration::from_secs(1));
                            let secs = elapsed.as_secs_f64();
                            let non_space = current_lesson_full.chars().filter(|c| *c!=' ').count() as f64;
                            let words = non_space / 5.0;
                            let wpm = if secs>0.0 { (words / (secs/60.0)) as usize } else { 0 };
                            let acc = if total_keystrokes==0 { 100 } else { ((total_keystrokes - wrong_keystrokes) as f64 / total_keystrokes as f64 * 100.0) as usize };
                            wpm_history.push(wpm);
                            acc_history.push(acc);
                            if wpm >= wpm_thresh && acc >= acc_thresh {
                                success_count+=1;
                            } else {
                                fail_count+=1;
                            }
                            lesson_num+=1;
                            current_lesson_full = generate_lesson(&source_list, combi, rep);
                            input_buffer.clear();
                            total_keystrokes=0;
                            wrong_keystrokes=0;
                            start_time=None;
                        }
                    }
                    KeyCode::Char(c) => {
                        if start_time.is_none() {
                            start_time = Some(Instant::now());
                        }
                        total_keystrokes+=1;
                        let mapped = if let Some(ref map) = emu_mapping {
                            if let Some(&mc) = map.get(&c) {
                                mc
                            } else {
                                c
                            }
                        } else {
                            c
                        };
                        let expected = current_lesson_full.chars().nth(input_buffer.len());
                        if let Some(exp) = expected {
                            if mapped != exp {
                                wrong_keystrokes+=1;
                            }
                        } else {
                            wrong_keystrokes+=1;
                        }
                        input_buffer.push(mapped);
                    }
                    _ => {}
                }
            }
        }
    }

    let mut out = io::stdout();
    let _ = out.execute(LeaveAlternateScreen);
    let _ = crossterm::terminal::disable_raw_mode();
    let _ = out.execute(cursor::Show);
}
RS
./compile.sh 2>&1 | tail -n 10
./executable --help 2>&1
"}

