        std::process::exit(1);
    }

    let source_list: Vec<String> = if n_arg == "2" {
        let t = std::cmp::min(top, BIGRAMS.len());
        BIGRAMS[..t].iter().map(|s| s.to_string()).collect()
    } else if n_arg == "3" {
        let t = std::cmp::min(top, TRIGRAMS.len());
        TRIGRAMS[..t].iter().map(|s| s.to_string()).collect()
