        for k in row2_keys {
            s.push_str(&format!(" {} │", k));
        }
        s
    };
    let bot_bottom = {
        let mut s = String::from("└");
        for i in 0..10 {
            s.push_str("───");
            if i!=9 { s.push_str("┴"); } else { s.push_str("┘"); }
        }
        s
    };
    let ortho_mid_sep = {
        let mut s = String::from("├");
        for i in 0..12 {
            s.push_str("───");
            if i!=11 { s.push_str("┼"); } else { s.push_str("┤"); }
