        write!(out, "│{}\x1b[38;5;2m{}\x1b[38;5;1m{}\x1b[39m│\r\n", prefix, check_part, cross_part).unwrap();
        write!(out, "│─────────────────────────────────────────────────────────────────────────────│\r\n").unwrap();
        write!(out, "│{:77}│\r\n", "").unwrap();
        write!(out, "{}\r\n", target_line_str).unwrap();
        write!(out, "{}\r\n", second_line_str).unwrap();
        write!(out, "│{:77}│\r\n", "").unwrap();

        if !nokb {
            if show_ortho {
                write!(out, "│\x1b[38;5;7m{}{}{}\x1b[39m│\r\n", " ".repeat(13), top_box, " ".repeat(15)).unwrap();
                write!(out, "│\x1b[38;5;7m{}{}{}\x1b[39m│\r\n", " ".repeat(13), top_keys_line, " ".repeat(15)).unwrap();
                write!(out, "│\x1b[38;5;7m{}{}{}\x1b[39m│\r\n", " ".repeat(13), ortho_mid_sep, " ".repeat(15)).unwrap();
                write!(out, "│\x1b[38;5;7m{}{}{}\x1b[39m│\r\n", " ".repeat(13), ortho_mid_keys, " ".repeat(15)).unwrap();
                write!(out, "│\x1b[38;5;7m{}{}{}\x1b[39m│\r\n", " ".repeat(13), ortho_mid_sep, " ".repeat(15)).unwrap();
                write!(out, "│\x1b[38;5;7m{}{}{}\x1b[39m│\r\n", " ".repeat(13), ortho_bot_keys, " ".repeat(15)).unwrap();
                write!(out, "│\x1b[38;5;7m{}{}{}\x1b[39m│\r\n", " ".repeat(13), ortho_bot_bottom, " ".repeat(15)).unwrap();
            } else {
                write!(out, "│\x1b[38;5;7m{}{}{}\x1b[39m│\r\n", " ".repeat(13), top_box, " ".repeat(15)).unwrap();
                write!(out, "│\x1b[38;5;7m{}{}{}\x1b[39m│\r\n", " ".repeat(13), top_keys_line, " ".repeat(15)).unwrap();
                write!(out, "│\x1b[38;5;7m{}{}{}\x1b[39m│\r\n", " ".repeat(13), top_bottom, " ".repeat(15)).unwrap();
                write!(out, "│\x1b[38;5;7m{}{}{}\x1b[39m│\r\n", " ".repeat(14), mid_keys_line, " ".repeat(18)).unwrap();
                write!(out, "│\x1b[38;5;7m{}{}{}\x1b[39m│\r\n", " ".repeat(14), mid_bottom, " ".repeat(18)).unwrap();
                write!(out, "│\x1b[38;5;7m{}{}{}\x1b[39m│\r\n", " ".repeat(15), bot_keys_line, " ".repeat(21)).unwrap();
                write!(out, "│\x1b[38;5;7m{}{}{}\x1b[39m│\r\n", " ".repeat(15), bot_bottom, " ".repeat(21)).unwrap();
            }
            writeln!(out, "│─────────────────────────────────────────────────────────────────────────────│\r").unwrap();
            writeln!(out, "│\x1b[38;5;7m  need >= {:3}WPM,   avg. \x1b[39m{:3}WPM\x1b[38;5;7m,   last \x1b[39m{:3}WPM                               │\r", wpm_thresh, avg_wpm, last_wpm).unwrap();
            writeln!(out, "│\x1b[38;5;7m  need >= {:3}% Acc, avg. \x1b[39m{:3}% Acc\x1b[38;5;7m, last \x1b[39m{:3}% Acc                             │\r", acc_thresh, avg_acc, last_acc).unwrap();
            writeln!(out, "╰─────────────────────────────────────────────────────────────────────────────╯\r").unwrap();
        } else {
            writeln!(out, "│─────────────────────────────────────────────────────────────────────────────│\r").unwrap();
            if cat {
                writeln!(out, "│\x1b[38;5;7m  need >= {:3}WPM,   avg. \x1b[39m{:3}WPM\x1b[38;5;7m,   last \x1b[39m{:3}WPM                  /\\_/\\        │\r", wpm_thresh, avg_wpm, last_wpm).unwrap();
                writeln!(out, "│\x1b[38;5;7m  need >= {:3}% Acc, avg. \x1b[39m{:3}% Acc\x1b[38;5;7m, last \x1b[39m{:3}% Acc               >(•༝• )<      │\r", acc_thresh, avg_acc, last_acc).unwrap();
                writeln!(out, "╰────────────────────────────────────────────────────────────    |    \\───────╯\r").unwrap();
            } else {
                writeln!(out, "│\x1b[38;5;7m  need >= {:3}WPM,   avg. \x1b[39m{:3}WPM\x1b[38;5;7m,   last \x1b[39m{:3}WPM                               │\r", wpm_thresh, avg_wpm, last_wpm).unwrap();
                writeln!(out, "│\x1b[38;5;7m  need >= {:3}% Acc, avg. \x1b[39m{:3}% Acc\x1b[38;5;7m, last \x1b[39m{:3}% Acc                             │\r", acc_thresh, avg_acc, last_acc).unwrap();
                writeln!(out, "╰─────────────────────────────────────────────────────────────────────────────╯\r").unwrap();
            }
        }

        out.flush().unwrap();

        if event::poll(Duration::from_millis(50)).unwrap() {
            if let Event::Key(key) = event::read().unwrap() {
                if key.kind != KeyEventKind::Press { continue; }
                match key.code {
                    KeyCode::Esc => break,
                    KeyCode::Backspace => {
                        if !input_buffer.is_empty() {
                            input_buffer.pop();
                            total_keystrokes+=1;
                        }
                    }
                    KeyCode::Enter => {
                        if input_buffer.len() >= current_lesson_full.len() {
                            let elapsed = start_time.map(|s| s.elapsed()).unwrap_or(Duration::from_secs(1));
                            let secs = elapsed.as_secs_f64();
                            let non_space = current_lesson_full.chars().filter(|c| *c!=' ').count() as f64;
                            let words = non_space / 5.0;
                            let wpm = if secs>0.0 { (words / (secs/60.0)) as usize } else { 0 };
                            let acc = if total_keystrokes==0 { 100 } else { ((total_keystrokes - wrong_keystrokes) as f64 / total_keystrokes as f64 * 100.0) as usize };
                            wpm_history.push(wpm);
                            acc_history.push(acc);
                            if wpm >= wpm_thresh && acc >= acc_thresh {
                                success_count+=1;
                            } else {
                                fail_count+=1;
                            }
                            lesson_num+=1;
                            current_lesson_full = generate_lesson(&source_list, combi, rep);
                            input_buffer.clear();
                            total_keystrokes=0;
                            wrong_keystrokes=0;
                            start_time=None;
                        }
                    }
                    KeyCode::Char(c) => {
                        if start_time.is_none() {
                            start_time = Some(Instant::now());
                        }
                        total_keystrokes+=1;
                        let mapped = if let Some(ref map) = emu_mapping {
                            if let Some(&mc) = map.get(&c) {
                                mc
                            } else {
                                c
                            }
                        } else {
                            c
                        };
                        let expected = current_lesson_full.chars().nth(input_buffer.len());
                        if let Some(exp) = expected {
                            if mapped != exp {
                                wrong_keystrokes+=1;
                            }
                        } else {
                            wrong_keystrokes+=1;
                        }
                        input_buffer.push(mapped);
                    }
                    _ => {}
                }
            }
        }
    }

    let mut out = io::stdout();
    let _ = out.execute(LeaveAlternateScreen);
    let _ = crossterm::terminal::disable_raw_mode();
    let _ = out.execute(cursor::Show);
}
RS
./compile.sh 2>&1 | tail -n 10
./executable --help 2>&1 | head -n 20
./executable --nokb -n 2 -t 1 -c 1 -r 1 --wpm 1 --acc 0 2>&1; echo exit:$?
echo "test file not found"
./executable --nokb -n notexist.txt 2>&1; echo exit:$?
echo "test emu"
