fn layout_flat(name: &str) -> Vec<String> {
    match name {
        "qwerty" => vec!["q","w","e","r","t","y","u","i","o","p","[","]","a","s","d","f","g","h","j","k","l",";","'","z","x","c","v","b","n","m",",",".","/"].into_iter().map(|s| s.to_string()).collect(),
        "qwertz" => vec!["q","w","e","r","t","z","u","i","o","p","ü","+","a","s","d","f","g","h","j","k","l","ö","ä","y","x","c","v","b","n","m",",",".","-"].into_iter().map(|s| s.to_string()).collect(),
        "azerty" => vec!["a","z","e","r","t","y","u","i","o","p","^","$","q","s","d","f","g","h","j","k","l","m","ù","w","x","c","v","b","n",",",";",":","!"].into_iter().map(|s| s.to_string()).collect(),
        "dvorak" => vec!["'".to_string(),",".to_string(),".".to_string(),"p".to_string(),"y".to_string(),"f".to_string(),"g".to_string(),"c".to_string(),"r".to_string(),"l".to_string(),"/".to_string(),"=".to_string(),"a".to_string(),"o".to_string(),"e".to_string(),"u".to_string(),"i".to_string(),"d".to_string(),"h".to_string(),"t".to_string(),"n".to_string(),"s".to_string(),"-".to_string(),";".to_string(),"q".to_string(),"j".to_string(),"k".to_string(),"x".to_string(),"b".to_string(),"m".to_string(),"w".to_string(),"v".to_string(),"z".to_string()],
        "colemak" => vec!["q","w","f","p","g","j","l","u","y",";","[","]","a","r","s","t","d","h","n","e","i","o","'","z","x","c","v","b","k","m",",",".","/"].into_iter().map(|s| s.to_string()).collect(),
        "colemakdh" => vec!["q","w","f","p","b","j","l","u","y",";","[","]","a","r","s","t","g","m","n","e","i","o","'","z","x","c","d","v","k","h",",",".","/"].into_iter().map(|s| s.to_string()).collect(),
        _ => vec!["q","w","e","r","t","y","u","i","o","p","[","]","a","s","d","f","g","h","j","k","l",";","'","z","x","c","v","b","n","m",",",".","/"].into_iter().map(|s| s.to_string()).collect(),
    }
}

fn build_mapping(in_name: &str, out_name: &str) -> HashMap<char, char> {
    let in_flat = layout_flat(in_name);
    let out_flat = layout_flat(out_name);
    let mut map = HashMap::new();
    for (ci, co) in in_flat.iter().zip(out_flat.iter()) {
        if let (Some(c_in), Some(c_out)) = (ci.chars().next(), co.chars().next()) {
            map.insert(c_in, c_out);
            if c_in.is_ascii_lowercase() {
                let upper_in = c_in.to_ascii_uppercase();
                let upper_out = c_out.to_ascii_uppercase();
                map.insert(upper_in, upper_out);
            }
        }
    }
    map
}

fn generate_lesson(source: &[String], combi: usize, rep: usize) -> String {
    let mut rng = thread_rng();
    let mut block: Vec<String> = Vec::new();
    for _ in 0..combi {
        if let Some(choice) = source.choose(&mut rng) {
            block.push(choice.clone());
        }
    }
    let mut tokens: Vec<String> = Vec::new();
    for _ in 0..rep {
        for b in &block {
            tokens.push(b.clone());
        }
    }
    tokens.join(" ")
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let mut args_iter = args.iter().skip(1).peekable();

    let mut n_arg = "2".to_string();
    let mut top: usize = 50;
    let mut combi: usize = 2;
    let mut rep: usize = 3;
    let mut wpm_thresh: usize = 40;
    let mut acc_thresh: usize = 94;
    let mut emu_in = String::new();
    let mut emu_out = String::new();
    let mut show_ortho = false;
    let mut nokb = false;
    let mut cat = false;

    let help_text = "Usage: executable [OPTIONS]\n\nOptions:\n  -n, --n <2|3|4|w|file>  use bi-(2), tri-(3), tetragrams(4), (w)ords or comma separated wordlist file. [default: 2]\n  -t, --top <1-200>       use the top X ngrams ordered by usage. [default: 50]\n  -c, --combi <1-200>     how many different ngrams to use in a single lesson. [default: 2]\n  -r, --rep <number>      how often to repeat *each* different ngram in a lesson. [default: 3]\n  -w, --wpm <number>      the wpm threshold at which the lesson is considered a success. [default: 40]\n  -a, --acc <0-100>       the accuracy in percent at which the lesson is considered a success. [default: 94]\n      --emu-in <layout>   your current keyboard layout. only needed if you want to emulate a different layout. see docs for supported layouts. [default: ]\n      --emu-out <layout>  the layout you want to emulate. only needed if you want to emulate a different layout. see docs for supported layouts. [default: ]\n      --show-ortho        show keyboard in ortholinear format\n      --nokb              pass this flag to disable the keyboard layout display.\n      --cat               the most important flag. don't practice alone.\n  -h, --help              Print help\n";

    while let Some(arg) = args_iter.next() {
        match arg.as_str() {
            "-h" | "--help" => {
                print!("{}", help_text);
                return;
            }
            "-n" | "--n" => {
                if let Some(v) = args_iter.next() {
                    n_arg = v.clone();
                } else {
                    eprintln!("error: a value is required for '-n <2|3|4|w|file>' but none was supplied\n\nFor more information, try '--help'.\n");
                    std::process::exit(2);
                }
            }
            "-t" | "--top" => {
                if let Some(v) = args_iter.next() {
                    match v.parse::<usize>() {
                        Ok(val) if val>=1 && val<=200 => top = val,
                        _ => {
                            eprintln!("Invalid argument for top. Use a number between 1 and 200.");
                            std::process::exit(1);
                        }
                    }
                } else {
                    eprintln!("error: a value is required for '--top <1-200>' but none was supplied\n\nFor more information, try '--help'.\n");
                    std::process::exit(2);
                }
            }
            "-c" | "--combi" => {
                if let Some(v) = args_iter.next() {
                    match v.parse::<usize>() {
                        Ok(val) if val>=1 && val<=200 => combi = val,
                        _ => {
                            eprintln!("Invalid argument for combi. Use a number between 1 and 200.");
                            std::process::exit(1);
                        }
                    }
                } else {
                    eprintln!("error: a value is required for '--combi <1-200>' but none was supplied\n\nFor more information, try '--help'.\n");
                    std::process::exit(2);
                }
            }
            "-r" | "--rep" => {
                if let Some(v) = args_iter.next() {
