fn layout_flat(name: &str) -> Vec<String> {
    match name {
        "qwerty" => vec!["q","w","e","r","t","y","u","i","o","p","[","]","a","s","d","f","g","h","j","k","l",";","'","z","x","c","v","b","n","m",",",".","/"].into_iter().map(|s| s.to_string()).collect(),
        "qwertz" => vec!["q","w","e","r","t","z","u","i","o","p","ü","+","a","s","d","f","g","h","j","k","l","ö","ä","y","x","c","v","b","n","m",",",".","-"].into_iter().map(|s| s.to_string()).collect(),
        "azerty" => vec!["a","z","e","r","t","y","u","i","o","p","^","$","q","s","d","f","g","h","j","k","l","m","ù","w","x","c","v","b","n",",",";",":","!"].into_iter().map(|s| s.to_string()).collect(),
        "dvorak" => vec!["'".to_string(),",".to_string(),".".to_string(),"p".to_string(),"y".to_string(),"f".to_string(),"g".to_string(),"c".to_string(),"r".to_string(),"l".to_string(),"/".to_string(),"=".to_string(),"a".to_string(),"o".to_string(),"e".to_string(),"u".to_string(),"i".to_string(),"d".to_string(),"h".to_string(),"t".to_string(),"n".to_string(),"s".to_string(),"-".to_string(),";".to_string(),"q".to_string(),"j".to_string(),"k".to_string(),"x".to_string(),"b".to_string(),"m".to_string(),"w".to_string(),"v".to_string(),"z".to_string()],
        "colemak" => vec!["q","w","f","p","g","j","l","u","y",";","[","]","a","r","s","t","d","h","n","e","i","o","'","z","x","c","v","b","k","m",",",".","/"].into_iter().map(|s| s.to_string()).collect(),
        "colemakdh" => vec!["q","w","f","p","b","j","l","u","y",";","[","]","a","r","s","t","g","m","n","e","i","o","'","z","x","c","d","v","k","h",",",".","/"].into_iter().map(|s| s.to_string()).collect(),
        _ => vec!["q","w","e","r","t","y","u","i","o","p","[","]","a","s","d","f","g","h","j","k","l",";","'","z","x","c","v","b","n","m",",",".","/"].into_iter().map(|s| s.to_string()).collect(),
    }
}

fn build_mapping(in_name: &str, out_name: &str) -> HashMap<char, char> {
    let in_flat = layout_flat(in_name);
    let out_flat = layout_flat(out_name);
    let mut map = HashMap::new();
    for (ci, co) in in_flat.iter().zip(out_flat.iter()) {
        if let (Some(c_in), Some(c_out)) = (ci.chars().next(), co.chars().next()) {
            map.insert(c_in, c_out);
            if c_in.is_ascii_lowercase() {
                let upper_in = c_in.to_ascii_uppercase();
                let upper_out = c_out.to_ascii_uppercase();
                map.insert(upper_in, upper_out);
            }
        }
    }
    map
}

fn generate_lesson(source: &[String], combi: usize, rep: usize) -> String {
    let mut rng = thread_rng();
    let mut block: Vec<String> = Vec::new();
    for _ in 0..combi {
        if let Some(choice) = source.choose(&mut rng) {
            block.push(choice.clone());
        }
    }
    let mut tokens: Vec<String> = Vec::new();
    for _ in 0..rep {
        for b in &block {
            tokens.push(b.clone());
        }
    }
    tokens.join(" ")
}

